#!/usr/bin/env python3
"""Check this install's pi configuration against the schemas pi itself ships.

pi validates models.json, settings.json and every theme it loads, and a value
it no longer accepts costs more than a warning: an invalid models.json drops
the whole provider it belongs to. pi 1.4.0 did exactly that to the elm
provider over "thinkingFormat": "reasoning_effort" - Qwen vanished and only
Llama was left - and rejected one of awesome-pi-themes' themes on every
launch. Both were visible only once the new release was already active.

So bootstrap.sh runs this against the pi it has just installed, before the
previous release is thrown away, and tests/ runs it against templates/. The
schemas come from the release under test (--schemas), never from pi.dev.

    check_config.py --root DIR [--schemas DIR] [--config] [--themes] [--rules]

--config checks agent/models.json and agent/settings.json; --themes checks the
theme files the configured packages would load; --rules checks the rule keys
of agent/extensions/pi-permission-system/config.json (see rule_problems),
which needs no schemas. With none, all three. Prints one line per problem and
exits 1 if there are any. Standard library only, and only the JSON Schema
keywords pi's schemas use: an unknown keyword is a problem in this script,
reported rather than silently passed.
"""

from __future__ import annotations

import argparse
import fnmatch
import json
import re
import sys
from pathlib import Path

PI_SCHEMAS = "node_modules/@earendil-works/pi-coding-agent/schemas"

# Keywords that carry no constraint, and the ones validate() implements.
ANNOTATIONS = {"$schema", "$id", "$comment", "title", "description", "default", "deprecated", "$defs"}
HANDLED = {"$ref", "anyOf", "const", "enum", "type", "minLength", "pattern", "minimum", "maximum",
           "exclusiveMinimum", "items", "maxItems", "required", "properties", "patternProperties",
           "additionalProperties"}

TYPES = {
    "string": lambda v: isinstance(v, str),
    "boolean": lambda v: isinstance(v, bool),
    # bool is an int in Python and never a number in JSON; 2.0 is an integer
    # to JSON Schema, as to pi's JavaScript
    "integer": lambda v: (isinstance(v, int) and not isinstance(v, bool)) or (isinstance(v, float) and v.is_integer()),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "null": lambda v: v is None,
}


def validate(value, schema, root: dict, path: str, problems: list[str]) -> None:
    if schema is True:
        return
    if schema is False:
        problems.append(f"{path}: not allowed here")
        return
    unknown = set(schema) - ANNOTATIONS - HANDLED
    if unknown:
        problems.append(f"{path}: schema keyword(s) {sorted(unknown)} not understood by check_config.py")
    if "$ref" in schema:
        ref = schema["$ref"]
        if not ref.startswith("#/"):
            problems.append(f"{path}: cannot resolve $ref {ref}")
            return
        target = root
        for part in ref[2:].split("/"):
            target = target[part]
        validate(value, target, root, path, problems)
    if "anyOf" in schema:
        branches = schema["anyOf"]
        if not any(_passes(value, branch, root) for branch in branches):
            consts = [b["const"] for b in branches if isinstance(b, dict) and "const" in b]
            if len(consts) == len(branches):
                problems.append(f"{path}: {json.dumps(value)} is not one of {', '.join(json.dumps(c) for c in consts)}")
            else:
                problems.append(f"{path}: {_brief(value)} matches none of the allowed forms")
    if "const" in schema and value != schema["const"]:
        problems.append(f"{path}: must be {json.dumps(schema['const'])}, not {_brief(value)}")
    if "enum" in schema and value not in schema["enum"]:
        problems.append(f"{path}: {_brief(value)} is not one of {schema['enum']}")
    if "type" in schema:
        allowed = schema["type"] if isinstance(schema["type"], list) else [schema["type"]]
        if not any(TYPES[t](value) for t in allowed):
            problems.append(f"{path}: expected {' or '.join(allowed)}, not {_brief(value)}")
            return
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0):
            problems.append(f"{path}: shorter than {schema['minLength']} characters")
        if "pattern" in schema and not re.search(schema["pattern"], value):
            problems.append(f"{path}: {json.dumps(value)} does not match {schema['pattern']}")
    if TYPES["number"](value):
        if "minimum" in schema and value < schema["minimum"]:
            problems.append(f"{path}: below the minimum {schema['minimum']}")
        if "maximum" in schema and value > schema["maximum"]:
            problems.append(f"{path}: above the maximum {schema['maximum']}")
        if "exclusiveMinimum" in schema and value <= schema["exclusiveMinimum"]:
            problems.append(f"{path}: must be greater than {schema['exclusiveMinimum']}")
    if isinstance(value, list):
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            problems.append(f"{path}: more than {schema['maxItems']} items")
        if "items" in schema:
            for index, item in enumerate(value):
                validate(item, schema["items"], root, f"{path}[{index}]", problems)
    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                problems.append(f"{path}: missing required {key}")
        properties = schema.get("properties", {})
        patterns = schema.get("patternProperties", {})
        for key, item in value.items():
            matched = False
            if key in properties:
                validate(item, properties[key], root, f"{path}.{key}", problems)
                matched = True
            for pattern, sub in patterns.items():
                if re.search(pattern, key):
                    validate(item, sub, root, f"{path}.{key}", problems)
                    matched = True
            if not matched and "additionalProperties" in schema:
                extra = schema["additionalProperties"]
                if extra is False:
                    problems.append(f"{path}: unknown key {key}")
                else:
                    validate(item, extra, root, f"{path}.{key}", problems)


def _passes(value, schema, root: dict) -> bool:
    found: list[str] = []
    validate(value, schema, root, "", found)
    return not found


def _brief(value) -> str:
    text = json.dumps(value)
    return text if len(text) <= 40 else text[:37] + "..."


def check_file(path: Path, schema_path: Path) -> list[str]:
    try:
        value = json.loads(path.read_text())
    except (OSError, ValueError) as error:
        return [f"{path.name}: does not parse ({error})"]
    schema = json.loads(schema_path.read_text())
    problems: list[str] = []
    validate(value, schema, schema, path.name, problems)
    return problems


def config_problems(config_dir: Path, schemas: Path) -> list[str]:
    problems = []
    for name in ("models.json", "settings.json"):
        if (config_dir / name).is_file():
            problems += check_file(config_dir / name, schemas / name.replace(".json", ".schema.json"))
    return problems


# --- the permission gate's rules ------------------------------------------------
#
# pi-permission-system (third-party, not patched here) applies a surface's rules
# last-match-wins, in the order it reads them - from a JS object, which lists
# integer-like keys ("7", "22") before every other, whatever the file's order.
# Its `?` matches one UTF-16 unit rather than one character, so `?` and an emoji
# (two units) disagree. Neither is worth patching the package for while no
# shipped rule can meet it, so such keys are refused here instead: tests/ hold
# the shipped template to this, and --rules reports one in an install's config.

PERMISSIONS = "extensions/pi-permission-system/config.json"
INTEGER_LIKE = re.compile(r"0|[1-9][0-9]*")
WILDCARD_RUN = re.compile(r"[*?]+")


def pattern_problem(pattern: str) -> str | None:
    """Why the gate would not apply `pattern` as written, or None."""
    if INTEGER_LIKE.fullmatch(pattern) and int(pattern) < 2 ** 32 - 1:
        return "is integer-like, so the gate moves it before every other rule"
    # `?` beside a `*` (`?*`, `*?`) means "at least one more", the same in UTF-16
    # units as in characters; a lone `?`, or two in one run (`??*`), is not.
    for run in WILDCARD_RUN.findall(pattern):
        if "?" in run and ("*" not in run or run.count("?") > 1):
            return f"has `{run}`, which the gate counts in UTF-16 units, not characters; only `?*` or `*?` is safe"
    return None


def rule_problems(path: Path) -> list[str]:
    try:
        permission = json.loads(path.read_text()).get("permission", {})
    except (OSError, ValueError, AttributeError) as error:
        return [f"{path.name}: does not parse ({error})"]
    problems = []
    for surface, rules in permission.items():
        if not isinstance(rules, dict):
            continue
        for pattern in rules:
            why = pattern_problem(pattern)
            if why:
                problems.append(f"{path.name}: permission.{surface} rule {json.dumps(pattern)} {why}")
    return problems


def _selected(rel: str, filters: list[str] | None) -> bool:
    """pi's per-package resource filter: omitted loads everything, [] loads
    nothing, "!glob" and "-path" exclude, a bare or "+" entry includes."""
    if filters is None:
        return True
    includes = [f.lstrip("+") for f in filters if not f.startswith(("!", "-"))]
    if not filters or (includes and not any(fnmatch.fnmatch(rel, p) for p in includes)):
        return False
    for entry in filters:
        if entry.startswith("!") and fnmatch.fnmatch(rel, entry[1:]):
            return False
        if entry.startswith("-") and rel == entry[1:]:
            return False
    return True


def theme_files(root: Path) -> list[Path]:
    settings = json.loads((root / "agent/settings.json").read_text())
    files = []
    for spec in settings.get("packages", []):
        filters = spec.get("themes") if isinstance(spec, dict) else None
        source = spec["source"] if isinstance(spec, dict) else spec
        pkg = root / "agent/npm/node_modules" / (source[4:] if source.startswith("npm:") else source)
        try:
            manifest = json.loads((pkg / "package.json").read_text()).get("pi") or {}
        except (OSError, ValueError):
            continue  # verify_install.py reports a missing package
        for entry in manifest.get("themes") or ([] if manifest else ["themes"]):
            base = pkg / entry
            candidates = sorted(base.glob("*.json")) if base.is_dir() else sorted(pkg.glob(entry))
            files += [f for f in candidates if _selected(f.relative_to(pkg).as_posix(), filters)]
    return files


def theme_problems(root: Path, schemas: Path) -> list[str]:
    problems = []
    for path in theme_files(root):
        found = check_file(path, schemas / "theme.schema.json")
        if found:
            rel = path.relative_to(root / "agent/npm/node_modules").as_posix()
            problems.append(f"theme {rel}: " + "; ".join(p.split(": ", 1)[1] for p in found))
    return problems


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--schemas", type=Path, help=f"default: <root>/{PI_SCHEMAS}")
    parser.add_argument("--config", action="store_true", help="agent/models.json and agent/settings.json")
    parser.add_argument("--themes", action="store_true", help="the themes the packages would load")
    parser.add_argument("--rules", action="store_true", help=f"the rule keys of agent/{PERMISSIONS}")
    args = parser.parse_args()
    root = args.root.resolve()
    schemas = (args.schemas or root / PI_SCHEMAS).resolve()
    every = not (args.config or args.themes or args.rules)
    if (args.config or args.themes or every) and not (schemas / "models.schema.json").is_file():
        print(f"    no pi schemas at {schemas}")
        return 1
    problems = []
    if args.config or every:
        problems += config_problems(root / "agent", schemas)
    if args.themes or every:
        problems += theme_problems(root, schemas)
    if (args.rules or every) and (root / "agent" / PERMISSIONS).is_file():
        problems += rule_problems(root / "agent" / PERMISSIONS)
    for problem in problems:
        print(f"    {problem}")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())

/**
 * command-output: draws a finished `bash` result for a person to read - an exit
 * line, the start and the end of the output, and colour - and gives the model
 * the same output without escape codes.
 *
 * Why: pi passes a command's output to the model as printed, colour codes and
 * progress-bar redraws (`\r`) included, and only its display strips them: it
 * shows the last five lines in one grey. So Qwen paid tokens to read
 * `\x1b[31m`, while the first error of a build and the file it names were
 * usually above those five lines, and a passing run looked like a failing one.
 *
 * When the output has escape codes, the model's copy becomes plain text (what
 * a terminal would have left on screen) and the colour version goes into the
 * result's `details`, which only the display reads - the provider sends
 * `content` alone, and pi's saved copy of a long output is made plain too.
 * The plain copy is the text the same command gives without colour: tabs and
 * control bytes are left for the display to draw, and a long output is cut
 * where pi would have cut it plain, not sooner for its colour codes' bytes.
 * Output without escape codes reaches the model unchanged.
 * When colour reached the display, the model's copy says so in one line:
 * without it Qwen cannot tell a rainbow from no colour, and claimed one.
 * The display shows a command's own colour (agent/shell/colour.sh turns it on)
 * as it printed it, on the terminal's own background, and colours everything
 * else by recognising lines:
 * errors, warnings, passes, diffs, `file:line` locations. A result that is
 * still streaming keeps pi's own live view and timer.
 */

import { readFileSync, statSync, writeFileSync } from "node:fs";
import type { ExtensionAPI, Theme, ThemeColor, TruncationResult } from "@earendil-works/pi-coding-agent";
import { DEFAULT_MAX_BYTES, formatSize, keyHint, truncateTail } from "@earendil-works/pi-coding-agent";
import type { Component } from "@earendil-works/pi-tui";
import { Container, getCapabilities, Text, visibleWidth, wrapTextWithAnsi } from "@earendil-works/pi-tui";

// Added to the model's copy, never drawn: the display shows the colour itself.
export const COLOUR_NOTE = "[The user saw this output in colour; the colour codes were taken out of your copy.]";

// Collapsed view: the first lines say what ran, the last ones how it ended.
const HEAD_LINES = 4;
const TAIL_LINES = 12;

export type Kind = "error" | "warning" | "success" | "added" | "removed" | "hunk" | "meta" | "plain";

const COLOUR: Record<Kind, ThemeColor> = {
	error: "error",
	warning: "warning",
	success: "success",
	added: "toolDiffAdded",
	removed: "toolDiffRemoved",
	hunk: "accent",
	meta: "muted",
	plain: "toolOutput",
};

// "0 errors", "no failures": a count of nothing is not a problem.
const NOTHING = /\b(?:0|no|zero)\s+(?:errors?|failures?|failed|warnings?)\b/gi;
// Nor is a label for a count: valgrind's `ERROR SUMMARY: 0 errors`, and
// unittest's `OK (expected failures=1)`, failures the tests were meant to have.
const LABELS = /\bERROR SUMMARY:|\bexpected failures?\b/gi;
// A word followed by an extension is a file name (src/errors.rs), not a report.
const ERROR_WORDS =
	/\b(?:error|errors|failed|failure|failures|fatal|exception|traceback|panic(?:ked)?|segmentation fault|core dumped|permission denied|connection refused|could not|no such file|not found|undefined reference|aborted)\b(?!\.[A-Za-z])/i;
// Case matters for these: ValueError and OSError, pytest's `E   assert`, Go's
// FAIL and `--- FAIL: TestSlope`, npm ERR!, TeX's `! Undefined control sequence.`.
const ERROR_MARKS = /[A-Za-z](?:Error|Exception)\b|^E\s|^\s*(?:--- )?FAIL\b|\bERR!|^! |[✗✘]/;
const WARNING = /\b(?:warn|warning|warnings|deprecated|deprecation)\b|⚠/i;
const WARNING_MARKS = /[a-z]Warning\b/;   // DeprecationWarning, RuntimeWarning
// A linter's finding: `fit.py:3:8: F401 ...` (ruff, flake8), `SC2086` (shellcheck).
const LINT = /:\d+(?::\d+)?:? [A-Z]{1,3}\d{2,4}\b|\bSC\d{4}\b/;
// pytest -v's PASSED, pip's `Successfully installed`, unittest's OK, Go's ok.
const SUCCESS = /\b(?:passed|succeeded|successfully|success)\b|^ok\b|[✓✔]|\bAll checks passed\b/i;
// src/fit.py:42:7, ./run.sh:3, and Python's `File "fit.py", line 42`.
const LOCATION = /(?:(?<![\w/.~-])(?:[A-Za-z]:)?[\w.~/@+-]*[\w-]\.[A-Za-z]\w*:\d+(?::\d+)?)|File "[^"]+", line \d+/g;

/** True when the output is a unified diff, so `+`/`-` lines are changes, not list items. */
export function isDiff(lines: string[]): boolean {
	return lines.some((line) => /^@@ -\d/.test(line) || line.startsWith("diff --git "));
}

export function classify(line: string, diff: boolean): Kind {
	if (diff) {
		if (/^(?:diff --git |index |\+\+\+ |--- )/.test(line)) return "meta";
		if (line.startsWith("@@")) return "hunk";
		if (line.startsWith("+")) return "added";
		if (line.startsWith("-")) return "removed";
		return "plain";
	}
	const text = line.replace(NOTHING, "").replace(LABELS, "");
	if (ERROR_WORDS.test(text) || ERROR_MARKS.test(text)) return "error";
	if (WARNING.test(text) || WARNING_MARKS.test(text) || LINT.test(text)) return "warning";
	if (SUCCESS.test(text)) return "success";
	return "plain";
}

/** One line in its kind's colour, with any file:line location in the accent colour. */
export function paintLine(line: string, kind: Kind, theme: Pick<Theme, "fg">): string {
	const colour = COLOUR[kind];
	if (kind === "added" || kind === "removed" || kind === "hunk" || kind === "meta") return theme.fg(colour, line);
	// Painted as separate runs: a nested colour would end with a reset and
	// leave the rest of the line uncoloured.
	let out = "";
	let at = 0;
	for (const match of line.matchAll(LOCATION)) {
		const start = match.index ?? 0;
		if (start > at) out += theme.fg(colour, line.slice(at, start));
		out += theme.fg("accent", match[0]);
		at = start + match[0].length;
	}
	if (at < line.length) out += theme.fg(colour, line.slice(at));
	return out;
}

export interface Outcome {
	/** The command's own output, without pi's status and truncation footers. */
	lines: string[];
	/** Lines the model was sent: more when pi truncated the output. */
	totalLines: number;
	status: string;
	failed: boolean;
	fullOutputPath?: string;
	/** The same output with the command's own colour codes, when it printed any. */
	colour?: string[];
	/** Text other extensions appended (install notes, attached figures). */
	notes: string[];
	images: number;
}

// What the panel draws: a tab as three spaces, nothing for other control bytes.
// Only the display does this - the model reads tabs and NULs as printed.
const onScreen = (text: string) => text.replace(/\t/g, "   ").replace(/[\x00-\x08\x0b-\x1a\x1c-\x1f\x7f]/g, "");

const strip = (text: string) =>
	onScreen(text.replace(/\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, "").replace(/\r/g, ""));

const COLOUR_CODE = /\x1b\[[0-9;:]*m/;
const COLOUR_CODES = /\x1b\[[0-9;:]*m/g;

/**
 * The output as a terminal would leave it: colour codes kept, every other
 * escape and `\r` redraw gone. Its text is what the same output printed without
 * colour turns into, so tabs and other control bytes stay.
 */
export function colourText(raw: string): string {
	const lines = raw.split("\n").map((line) => {
		// A line ending: git colours a CRLF line's \r and resets after it.
		line = line.replace(/(?:\r|\x1b\[[0-9;:]*m)+$/, (end) => end.replace(/\r/g, ""));
		// A progress bar redraws its line with \r: keep what it ended as.
		line = line.slice(line.lastIndexOf("\r") + 1);
		return line
			.replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, "")
			.replace(/\x1b\[[0-9;:?]*[ -/]*[@-~]/g, (seq) => (/^\x1b\[[0-9;:]*m$/.test(seq) ? seq : ""))
			// Any other escape ends at its first byte in 0-~: `tput sgr0`'s
			// charset reset ESC ( B, save-cursor ESC 7, reset ESC c.
			.replace(/\x1b(?!\[[0-9;:]*m)[ -/]*[0-~]?/g, "");
	});
	return lines.join("\n");
}

/** Output as the model should read it, and - when the command printed colour - as the display should show it. */
export function separate(text: string): { plain: string; colour?: string } {
	if (!/[\x1b\r]/.test(text)) return { plain: text };
	const colour = colourText(text);
	return { plain: colour.replace(COLOUR_CODES, ""), colour: COLOUR_CODE.test(colour) ? colour : undefined };
}

/**
 * Each line made to stand alone: it starts in the colour the previous line left
 * open and ends with a reset, so a colour never bleeds into pi's own rows.
 */
export function carryColour(lines: string[]): string[] {
	let open: string[] = [];
	return lines.map((line) => {
		const out = open.join("") + line;
		for (const match of line.matchAll(/\x1b\[([0-9;:]*)m/g)) {
			const params = match[1];
			if (params === "" || params === "0") open = [];
			else if (params.startsWith("0;")) open = [match[0]];
			// lolcat sets a colour per character and never resets: only the last few matter.
			else open = [...open, match[0]].slice(-8);
		}
		return COLOUR_CODE.test(out) ? `${out}\x1b[0m` : out;
	});
}

function seconds(ms: number): string {
	if (ms < 1000) return `${ms}ms`;
	// Rounded before the unit is chosen or the minutes split off, so 59960ms
	// reads 1m0s, not 60.0s, and 119999ms reads 2m0s, not 1m60s.
	if (Math.round(ms / 100) < 600) return `${(Math.round(ms / 100) / 10).toFixed(1)}s`;
	const s = Math.round(ms / 1000);
	return `${Math.floor(s / 60)}m${s % 60}s`;
}

interface ResultLike {
	content: Array<{ type: string; text?: string }>;
	details?: { truncation?: { truncated?: boolean; totalLines?: number }; fullOutputPath?: string; colour?: string };
	structuredContent?: unknown;
}

/** What a bash result says, read the way pi's bash tool writes it. */
export function readResult(result: ResultLike, isError: boolean, durationMs?: number): Outcome {
	const texts = result.content.filter((part) => part.type === "text").map((part) => strip(part.text ?? ""));
	let output = texts[0] ?? "";
	const notes = texts.slice(1).map((note) => note.trim()).filter((note) => note && note !== COLOUR_NOTE);
	const images = result.content.filter((part) => part.type === "image").length;

	// pi appends the status after a blank line: "Command exited with code 2",
	// "Command timed out after 30 seconds", "Command aborted".
	let status = "";
	const tail = /(?:^|\n\n)(Command (?:exited with code \d+|timed out after \d+ seconds|aborted|terminated without an exit code))$/.exec(output);
	if (tail) {
		status = tail[1];
		output = output.slice(0, tail.index);
	}
	const fullOutputPath = result.details?.fullOutputPath;
	if (fullOutputPath) {
		const footer = output.lastIndexOf("\n\n[");
		if (footer !== -1 && output.slice(footer).includes(fullOutputPath)) output = output.slice(0, footer);
	}
	output = output.replace(/\s+$/, "");
	const lines = output ? output.split("\n") : [];

	const code = (result.structuredContent as { exit_code?: unknown } | undefined)?.exit_code;
	const exitCode = typeof code === "number" ? code : status.startsWith("Command exited") ? Number(status.split(" ").pop()) : isError ? undefined : 0;
	const failed = isError || (exitCode !== undefined && exitCode !== 0);
	const what =
		exitCode !== undefined
			? `exit ${exitCode}`
			: status.replace(/^Command /, "").replace(/ seconds$/, "s") || "failed";
	const totalLines = result.details?.truncation?.truncated ? (result.details.truncation.totalLines ?? lines.length) : lines.length;
	const parts = [`${failed ? "✗" : "✓"} ${what}`];
	if (durationMs !== undefined) parts.push(seconds(durationMs));
	parts.push(`${totalLines} line${totalLines === 1 ? "" : "s"}`);
	// Line for line the same text as the model's copy, so the output's lines are its first lines.
	const colour = typeof result.details?.colour === "string" ? result.details.colour.split("\n").slice(0, lines.length).map(onScreen) : undefined;
	return { lines, totalLines, status: parts.join(" · "), failed, fullOutputPath, colour, notes, images };
}

/**
 * The lines to show, already painted: everything, or head + a hint + tail. With
 * the command's own colour, its lines are shown as it coloured them - and a line
 * it left plain stays plain - while the hidden-line counts still come from
 * reading the text.
 */
export function bodyLines(lines: string[], expanded: boolean, theme: Pick<Theme, "fg">, hint: () => string, colour?: string[]): string[] {
	if (colour) lines = colour.map((line) => line.replace(COLOUR_CODES, ""));
	const diff = isDiff(lines);
	const kinds = lines.map((line) => classify(line, diff));
	const own = colour && carryColour(colour);
	const paint = (i: number) => (own ? (COLOUR_CODE.test(own[i]) ? own[i] : theme.fg("toolOutput", own[i])) : paintLine(lines[i], kinds[i], theme));
	if (expanded || lines.length <= HEAD_LINES + TAIL_LINES + 1) return lines.map((_, i) => paint(i));
	const hiddenFrom = HEAD_LINES;
	const hiddenTo = lines.length - TAIL_LINES;
	const hiddenKinds = kinds.slice(hiddenFrom, hiddenTo);
	const errors = hiddenKinds.filter((kind) => kind === "error").length;
	const warnings = hiddenKinds.filter((kind) => kind === "warning").length;
	const flagged = [errors && `${errors} error`, warnings && `${warnings} warning`].filter(Boolean);
	let gap = theme.fg("muted", `… ${hiddenTo - hiddenFrom} lines hidden`);
	if (flagged.length) gap += theme.fg(errors ? "error" : "warning", `, ${flagged.join(" and ")} line${errors + warnings === 1 ? "" : "s"} among them`);
	gap += theme.fg("muted", " (") + hint() + theme.fg("muted", ")");
	return [
		...lines.slice(0, hiddenFrom).map((_, i) => paint(i)),
		gap,
		...lines.slice(hiddenTo).map((_, i) => paint(hiddenTo + i)),
	];
}

// Rewrites a saved output as plain text, and returns it as it was printed. pi
// has closed the file by the time the result reaches extensions; one too large
// to hold is left as it is.
export function plainFile(path: string): string | undefined {
	try {
		if (statSync(path).size > 64 * 1024 * 1024) return undefined;
		const text = readFileSync(path, "utf8");
		const { plain } = separate(text);
		if (plain !== text) writeFileSync(path, plain);
		return text;
	} catch {
		// Gone or unreadable: nothing to clean.
		return undefined;
	}
}

// What colour adds to an output: its codes, and the erase-to-end grep sends
// after each one.
const COLOURING = /(\x1b\[[0-9;:]*m|\x1b\[K)/g;

// The end of a coloured line holding the last `chars` characters of its text,
// opened with the code in force where it is cut.
function colourTail(line: string, chars: number): string {
	const parts = line.split(COLOURING);
	let out = "";
	for (let i = parts.length - 1; i >= 0; i -= 2) {
		if (parts[i].length >= chars) {
			const open = i > 0 ? parts[i - 1] : "";
			return open + parts[i].slice(parts[i].length - chars) + out;
		}
		chars -= parts[i].length;
		out = (i > 0 ? parts[i - 1] : "") + parts[i] + out;
	}
	return out;
}

/**
 * pi keeps the last 2000 lines or 50KB of an output, counting its colour codes
 * as bytes, so a coloured output gave the model fewer lines than the same output
 * plain. This makes the cut again from the saved output as printed, on its text
 * without colour codes, and gives pi's result text for it - still coloured, for
 * separate() - with pi's own footer and the status after it, and the truncation
 * for details (undefined when the plain output fits whole).
 */
export function recut(
	text: string,
	printed: string,
	path: string,
	limits: { maxLines?: number; maxBytes?: number } = {},
): { text: string; truncation?: TruncationResult } | undefined {
	const marker = `Full output: ${path}]`;
	const end = text.lastIndexOf(marker);
	if (end === -1 || text.lastIndexOf("\n\n[", end) === -1) return undefined;
	const status = text.slice(end + marker.length);
	const plain = printed.replace(COLOURING, "");
	const cut = truncateTail(plain, { maxLines: limits.maxLines, maxBytes: limits.maxBytes });
	if (!cut.truncated) return { text: `${printed || "(no output)"}${status}` };
	// Colour holds no newline, so the printed lines are the plain ones.
	const lines = printed.split("\n");
	if (printed.endsWith("\n")) lines.pop();
	let body: string;
	let footer: string;
	if (cut.lastLinePartial) {
		body = colourTail(lines[lines.length - 1], cut.content.length);
		const lastLine = formatSize(Buffer.byteLength(plain.slice(plain.lastIndexOf("\n") + 1), "utf8"));
		footer = `[Showing last ${formatSize(cut.outputBytes)} of line ${cut.totalLines} (line is ${lastLine}). ${marker}`;
	} else {
		body = lines.slice(lines.length - cut.outputLines).join("\n");
		const shown = `lines ${cut.totalLines - cut.outputLines + 1}-${cut.totalLines} of ${cut.totalLines}`;
		footer = cut.truncatedBy === "lines" ? `[Showing ${shown}. ${marker}` : `[Showing ${shown} (${formatSize(DEFAULT_MAX_BYTES)} limit). ${marker}`;
	}
	return { text: `${body || "(no output)"}\n\n${footer}${status}`, truncation: cut };
}

// The output sits on the terminal's own background, inside a margin of the
// tool box's colour: a command's colours were made for that background, and
// its reset (`\x1b[0m`) clears pi's tint anyway, so a rainbow came out in patches.
export class TerminalPanel implements Component {
	private rows: string[];
	private boxBg: string;
	private cache?: { width: number; lines: string[] };

	constructor(rows: string[], boxBg: string) {
		this.rows = rows;
		this.boxBg = boxBg;
	}

	invalidate(): void {
		this.cache = undefined;
	}

	render(width: number): string[] {
		if (this.cache?.width === width) return this.cache.lines;
		const inner = Math.max(1, width - 2);
		const lines = this.rows
			.flatMap((row) => (row ? wrapTextWithAnsi(row, inner) : [""]))
			.map((line) => `\x1b[49m ${line}${" ".repeat(Math.max(0, inner - visibleWidth(line)))} ${this.boxBg}`);
		this.cache = { width, lines };
		return lines;
	}
}

export default function commandOutput(pi: ExtensionAPI) {
	pi.on("tool_result", (event) => {
		if (event.toolName !== "bash") return;
		// pi saves a long output whole, as printed, for the model to `read` later;
		// its colour may sit in lines the result's own text leaves out.
		const saved = event.details as { fullOutputPath?: unknown; truncation?: TruncationResult } | undefined;
		const fullOutputPath = saved?.fullOutputPath;
		const printed = typeof fullOutputPath === "string" ? plainFile(fullOutputPath) : undefined;
		const first = event.content.findIndex((part) => part.type === "text");
		if (first === -1) return;
		const original = (event.content[first] as { text: string }).text;
		let text = original;
		let details = event.details;
		if (typeof fullOutputPath === "string" && printed !== undefined && saved?.truncation?.truncated && COLOUR_CODE.test(printed)) {
			const again = recut(text, printed, fullOutputPath, saved.truncation);
			if (again) {
				text = again.text;
				// Fitting whole once plain, it is a result pi would not have cut, and names no saved file.
				const { truncation: _cut, fullOutputPath: _path, ...rest } = saved;
				details = again.truncation ? { ...saved, truncation: again.truncation } : Object.keys(rest).length ? rest : undefined;
			}
		}
		const { plain, colour } = separate(text);
		if (plain === original && details === event.details) return;
		const content = event.content.map((part, i) => (i === first ? { ...part, text: plain } : part));
		if (colour) content.splice(first + 1, 0, { type: "text", text: COLOUR_NOTE });
		// structuredContent carries the output too (for codemode scripts), and
		// pi drops it when content is replaced without it.
		const structured = event.structuredContent as { output?: unknown } | undefined;
		const structuredContent =
			structured && typeof structured.output === "string" ? { ...structured, output: separate(structured.output).plain } : event.structuredContent;
		return { content, structuredContent, details: colour ? { ...details, colour } : details };
	});

	pi.registerToolRenderer((toolName, next) => {
		const base = next();
		if (toolName !== "bash" || !base) return base;
		return {
			...base,
			renderResult(result, options, theme, context) {
				if (options.isPartial && base.renderResult) return base.renderResult(result, options, theme, context);
				const component = context.lastComponent instanceof Container ? context.lastComponent : new Container();
				component.clear();
				const outcome = readResult(result as ResultLike, context.isError, context.durationMs);
				component.addChild(new Text(`\n${theme.fg(outcome.failed ? "error" : "success", theme.bold(outcome.status))}`, 0, 0));
				// pi 1.5 passes keyHint in the context: the imported one can be this
				// extension's own copy, which does not see the user's keybindings.
				const hint = (context as { keyHint?: typeof keyHint }).keyHint ?? keyHint;
				const body = bodyLines(outcome.lines, options.expanded, theme, () => hint("app.tools.expand", "to expand"), outcome.colour);
				// The same tint pi gives the box (tool-execution.js), restored after each line.
				if (body.length) component.addChild(new TerminalPanel(body, theme.getBgAnsi(context.isError ? "toolErrorBg" : "toolSuccessBg")));
				const rows: string[] = [];
				if (outcome.fullOutputPath) {
					const count = `${outcome.totalLines} line${outcome.totalLines === 1 ? "" : "s"}`;
					rows.push(theme.fg("muted", `full output (${count}): ${outcome.fullOutputPath}`));
				}
				for (const note of outcome.notes) rows.push(theme.fg("muted", note));
				if (outcome.images && !(getCapabilities().images && context.showImages)) {
					rows.push(theme.fg("muted", `[${outcome.images} image${outcome.images === 1 ? "" : "s"} attached, not shown in this terminal]`));
				}
				if (rows.length) component.addChild(new Text(rows.join("\n"), 0, 0));
				component.invalidate();
				return component;
			},
		};
	});
}

/**
 * install-notes: when the agent installs software, the user is told what, where
 * it lives and how to remove it, and agent/installs.log keeps the record.
 *
 * Why: the prompt and the installing-software skill both ask for it, and it was
 * not done. Measured: asked to look at an EPS file on a machine without
 * Ghostscript, Qwen found conda-forge's with `pixi exec`, converted the file and
 * described the figure correctly - and its report never said that anything had
 * been downloaded, or where. What an assistant leaves on a researcher's machine
 * should not depend on it remembering to mention it.
 *
 * So after a successful `bash` command that installs - pip/uv pip, uv add, pixi
 * exec, pixi global install, pixi add, docker/podman pull, brew install - its
 * result gets a note saying what went where and how to undo it, with the
 * instruction to pass it on, and the same line is appended to agent/installs.log.
 * Commands are recognised by name, within chains and subshells (`cd x && pip
 * install y`, `(cd x && pip install y)`); an install hidden inside a script is
 * not seen.
 */

import { accessSync, appendFileSync, constants } from "node:fs";
import { homedir } from "node:os";
import { delimiter, dirname, join, resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

export interface Install {
	what: string;
	where: string;
	undo: string;
}

const agentDir = () => process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent");

function onPath(tool: string): string | undefined {
	for (const dir of (process.env.PATH ?? "").split(delimiter)) {
		if (!dir) continue;
		try {
			accessSync(join(dir, tool), constants.X_OK);
			return join(dir, tool);
		} catch {
			// not in this one
		}
	}
	return undefined;
}

/** Shell-ish words of one command: quotes removed, no expansion, redirections dropped. */
function words(segment: string): string[] {
	const all = [...segment.matchAll(/"([^"]*)"|'([^']*)'|(\S+)/g)].map((m) => ({ word: m[1] ?? m[2] ?? m[3], bare: m[3] !== undefined }));
	const out: string[] = [];
	for (let i = 0; i < all.length; i++) {
		const { word, bare } = all[i];
		// 2>&1, >log, 2>/dev/null, &>out - and a lone > or 2> takes the next word with it.
		const redirect = bare ? /^(\d*|&)(>>?|<)(&?\S*)$/.exec(word) : null;
		if (redirect) {
			if (redirect[3] === "") i++;
			continue;
		}
		out.push(word);
	}
	return out;
}

/**
 * The commands of a command line, split at && || ; | & and newlines outside quotes,
 * with a subshell's parentheses as entries of their own: `(cd x && pip install y)`.
 */
function commands(line: string): string[] {
	const out: string[] = [];
	let current = "";
	let quote = "";
	const cut = (mark?: string) => {
		out.push(current.trim());
		if (mark) out.push(mark);
		current = "";
	};
	for (let i = 0; i < line.length; i++) {
		const c = line[i];
		if (c === "\\" && quote !== "'") {
			// an escaped character, or a line continuation, which joins the lines
			const next = line[++i] ?? "";
			if (next !== "\n") current += c + next;
		} else if (quote) {
			if (c === quote) quote = "";
			current += c;
		} else if (c === "'" || c === '"') {
			quote = c;
			current += c;
		} else if (c === "(" || c === ")") {
			cut(c);
		} else if (c === ";" || c === "\n" || c === "|") {
			if (c === "|" && line[i + 1] === "|") i++;
			cut();
		} else if (c === "&" && line[i + 1] === "&") {
			i++;
			cut();
		} else if (c === "&" && !/[<>]/.test(line[i - 1] ?? "") && line[i + 1] !== ">") {
			// a command sent to the background; 2>&1 and &>log are redirections
			cut();
		} else {
			current += c;
		}
	}
	cut();
	return out.filter((part) => part !== "");
}

/** The index of the first operand (or of `--`): where a subcommand, or the command an option-taking wrapper runs, is. */
function firstOperand(args: string[], valued: string[]): number {
	for (let i = 0; i < args.length; i++) {
		if (args[i] === "--" || !args[i].startsWith("-")) return i;
		if (valued.includes(args[i])) i++;
	}
	return args.length;
}

/** The operands after a subcommand: not options, and not the values of the options that take one. */
function operands(args: string[], valued: string[]): string[] {
	const out: string[] = [];
	for (let i = 0; i < args.length; i++) {
		const a = args[i];
		if (valued.includes(a)) i++;
		else if (!a.startsWith("-")) out.push(a);
	}
	return out;
}

/** The values given to these options, as `--opt value`, `--opt=value`, `-o value` or `-ovalue`. */
function optionValues(args: string[], flags: string[]): string[] {
	const out: string[] = [];
	for (let i = 0; i < args.length; i++) {
		const a = args[i];
		const eq = a.startsWith("--") ? a.indexOf("=") : -1;
		const attached = eq > 0 || /^-[^-]./.test(a);
		const flag = eq > 0 ? a.slice(0, eq) : attached ? a.slice(0, 2) : a;
		if (!flags.includes(flag)) continue;
		const value = eq > 0 ? a.slice(eq + 1) : attached ? a.slice(2) : args[++i];
		if (value !== undefined) out.push(value);
	}
	return out;
}

/** A help or dry run installs nothing, though it exits 0. */
const installsNothing = (args: string[]) => args.some((a) => a === "--help" || a === "-h" || a === "--dry-run");

/** Where `cd` with these arguments goes from `here`; `here` again when that cannot be told (`cd -`, `cd $DIR`). */
function cdTo(args: string[], here: string): string {
	const target = args[firstOperand(args, [])];
	if (target === undefined || target === "--") return homedir();
	if (target === "-" || /[$`]/.test(target)) return here;
	if (target === "~" || target.startsWith("~/")) return join(homedir(), target.slice(1));
	return resolve(here, target);
}

/** The commands that run the next one, with the options of each that take a value: `sudo -u ci pip install x`. */
const WRAPPERS = new Map<string, string[]>([
	["sudo", ["-u", "--user", "-g", "--group", "-C", "--close-from", "-D", "--chdir", "-h", "--host", "-p", "--prompt",
		"-r", "--role", "-t", "--type", "-T", "--command-timeout", "-U", "--other-user"]],
	["env", ["-u", "--unset", "-C", "--chdir", "-P"]],
	["time", ["-f", "--format", "-o", "--output"]],
]);

/** Every option of `pip install` that takes a value (pip 25.1's --help), so no value is taken for a package. */
const PIP_VALUED = [
	"-r", "--requirement", "-c", "--constraint", "-e", "--editable", "-t", "--target", "--platform",
	"--python-version", "--implementation", "--abi", "--root", "--prefix", "--src", "--upgrade-strategy",
	"-C", "--config-settings", "--global-option", "--no-binary", "--only-binary", "--progress-bar",
	"--root-user-action", "--report", "--group", "-i", "--index-url", "--extra-index-url", "-f", "--find-links",
	"--python", "--log", "--keyring-provider", "--proxy", "--retries", "--timeout", "--exists-action",
	"--trusted-host", "--cert", "--client-cert", "--cache-dir", "--use-feature", "--use-deprecated", "--resume-retries",
];
/** Those `uv pip install` adds to pip's. */
const UV_PIP_VALUED = [
	"-p", "--requirements", "--constraints", "--overrides", "-b", "--build-constraints", "--extra", "-P",
	"--upgrade-package", "--reinstall-package", "--refresh-package", "--index", "--default-index", "--index-strategy",
	"--resolution", "--prerelease", "--exclude-newer", "--no-build-isolation-package", "--config-setting",
	"--link-mode", "--python-platform", "--torch-backend", "--color", "--allow-insecure-host", "--config-file",
	"--directory", "--project",
];
/** The options of `uv add` that take a value. */
const UV_ADD_VALUED = [
	"-r", "--requirements", "-c", "--constraints", "-m", "--marker", "--optional", "--group", "--rev", "--tag",
	"--branch", "--extra", "--package", "--script", "--bounds", "--index", "--default-index", "-i", "--index-url",
	"--extra-index-url", "-f", "--find-links", "--index-strategy", "--keyring-provider", "--resolution",
	"--prerelease", "--exclude-newer", "--no-build-isolation-package", "-C", "--config-setting", "--link-mode",
	"-P", "--upgrade-package", "--reinstall-package", "--refresh-package", "-p", "--python", "--cache-dir",
	"--color", "--allow-insecure-host", "--config-file", "--directory", "--project",
];

/** pip's general options that take a value, which may come before `install` (pip 25.1's --help). */
const PIP_GENERAL_VALUED = [
	"--python", "--log", "--keyring-provider", "--proxy", "--retries", "--timeout", "--exists-action",
	"--trusted-host", "--cert", "--client-cert", "--cache-dir", "--use-feature", "--use-deprecated", "--resume-retries",
];
/** The options of `pixi add` that take a value. */
const PIXI_ADD_VALUED = [
	"-c", "--channel", "-f", "--feature", "-p", "--platform", "--manifest-path", "-g", "--git", "--branch", "--tag",
	"--rev", "-s", "--subdir", "--auth-file", "--concurrent-solves", "--concurrent-downloads",
];
/** The options of `pixi exec` that take a value; the first operand is the command it runs. */
const PIXI_EXEC_VALUED = [
	"-s", "--spec", "-w", "--with", "-c", "--channel", "-p", "--platform", "--auth-file", "--concurrent-solves",
	"--concurrent-downloads",
];
/** The options of `docker pull` and `podman pull` that take a value. */
const PULL_VALUED = [
	"--platform", "--arch", "--os", "--variant", "--authfile", "--cert-dir", "--creds", "--decryption-key", "--policy",
	"--retry", "--retry-delay",
];

/** What one shell command installs, or nothing. */
export function describe(command: string, cwd: string): Install[] {
	const found: Install[] = [];
	// A `cd` moves the project folder of the commands after it, until its subshell ends.
	let here = cwd;
	const outer: string[] = [];
	for (const part of commands(command)) {
		if (part === "(") {
			outer.push(here);
			continue;
		}
		if (part === ")") {
			here = outer.pop() ?? here;
			continue;
		}
		let w = words(part);
		// VAR=x cmd, sudo -H cmd, env VAR=x cmd, time cmd - in any order.
		for (;;) {
			const valued = WRAPPERS.get(w[0]);
			if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(w[0] ?? "")) w = w.slice(1);
			else if (valued) w = w.slice(1 + firstOperand(w.slice(1), valued)).filter((x, i) => i > 0 || x !== "--");
			else break;
		}
		if (!w.length) continue;
		const tool = w[0].split("/").pop() ?? w[0];
		if (tool === "cd") {
			here = cdTo(w.slice(1), here);
			continue;
		}
		const pixiHome = process.env.PIXI_HOME || join(agentDir(), "pixi");
		const pixiCache = process.env.PIXI_CACHE_DIR || join(pixiHome, "cache");

		// pip, pip3, pip3.11; python3 -m pip; uv pip - each with options before the subcommand allowed.
		const pipAt = /^pip(\d+(\.\d+)?)?$/.test(tool) ? 1
			: /^python(\d+(\.\d+)?)?$/.test(tool) && w[1] === "-m" && w[2] === "pip" ? 3
			: tool === "uv" && w[1] === "pip" ? 2
			: -1;
		const pipSub = pipAt < 0 ? -1 : pipAt + firstOperand(w.slice(pipAt), PIP_GENERAL_VALUED);

		if (tool === "pixi" && w[1] === "exec") {
			// Only pixi's own options: those after the command it runs are that command's (rg -s).
			const own = w.slice(2, 2 + firstOperand(w.slice(2), PIXI_EXEC_VALUED));
			if (installsNothing(own)) continue;
			const specs = optionValues(own, ["-s", "--spec", "-w", "--with"]);
			found.push({
				what: `${specs.join(", ") || "a package"} from conda-forge, run with pixi exec (nothing installed)`,
				where: `downloaded packages cached in ${pixiCache}`,
				undo: "pixi clean cache",
			});
		} else if (tool === "pixi" && w[1] === "global" && w[2] === "install") {
			if (installsNothing(w.slice(3))) continue;
			const pkgs = operands(w.slice(3), ["-c", "--channel", "-e", "--environment", "--expose", "-p", "--platform"]);
			found.push({
				what: `${pkgs.join(", ")} from conda-forge (pixi global install)`,
				where: `${join(pixiHome, "envs")}, with its commands in ${join(pixiHome, "bin")} on PATH`,
				undo: `pixi global uninstall ${pkgs.join(" ")}`,
			});
		} else if (tool === "pixi" && w[1] === "add") {
			const args = w.slice(2);
			if (installsNothing(args)) continue;
			const pkgs = operands(args, PIXI_ADD_VALUED);
			// --manifest-path names the manifest itself or the folder that holds it.
			const given = optionValues(args, ["--manifest-path"])[0];
			const manifest = given ? resolve(here, given.endsWith(".toml") ? given : join(given, "pixi.toml")) : join(here, "pixi.toml");
			found.push({
				what: `${pkgs.join(", ")} added to this project's pixi environment`,
				where: `${manifest} and ${join(dirname(manifest), ".pixi")}`,
				undo: `pixi remove ${pkgs.join(" ")}`,
			});
		} else if (tool === "uv" && w[1] === "add") {
			const args = w.slice(2);
			if (installsNothing(args)) continue;
			const pkgs = operands(args, UV_ADD_VALUED);
			const req = optionValues(args, ["-r", "--requirements"]).map((file) => `the packages in ${file}`);
			const project = resolve(here, optionValues(args, ["--project", "--directory"])[0] ?? ".");
			found.push({
				what: `${[...pkgs, ...req].join(", ")} from PyPI, added to this project's environment (uv add)`,
				where: `${join(project, "pyproject.toml")} and ${join(project, ".venv")}`,
				undo: `uv remove ${pkgs.join(" ") || "<package>"}`,
			});
		} else if (pipSub >= 0 && w[pipSub] === "install") {
			// The general options before `install` count with its own: `pip --python x install y`.
			const args = [...w.slice(pipAt, pipSub), ...w.slice(pipSub + 1)];
			if (installsNothing(args)) continue;
			const pkgs = operands(args, tool === "uv" ? [...PIP_VALUED, ...UV_PIP_VALUED] : PIP_VALUED);
			const req = optionValues(args, ["-r", "--requirement", "--requirements"]).map((file) => `the packages in ${file}`);
			const target = optionValues(args, ["-t", "--target"])[0];
			// --prefix and --root install under another tree than the environment's,
			// and --user into the account's own site-packages.
			const prefix = optionValues(args, ["--prefix"])[0];
			const root = optionValues(args, ["--root"])[0];
			const user = args.includes("--user");
			// A pip or python named by path is that one; a bare name is the first on PATH.
			const python =
				optionValues(args, ["--python", "-p"])[0] ??
				(tool !== "uv" ? (w[0].includes("/") ? w[0] : (onPath(tool) ?? tool))
				: process.env.VIRTUAL_ENV ? join(process.env.VIRTUAL_ENV, "bin/python")
				: undefined);
			const names = pkgs.join(" ") || "<package>";
			found.push({
				what: `${[...pkgs, ...req].join(", ") || "Python packages"} from PyPI`,
				where: target ? `the folder ${target}/ (--target), not a Python environment`
					: prefix ? `the prefix ${prefix}/ (--prefix), outside the Python environment`
					: root ? `under ${root}/ (--root), outside the Python environment`
					: user ? `your user site-packages (\`python3 -m site --user-site\`)`
					: python ? `the Python environment of ${python}`
					: "the environment uv chose",
				undo: target ? `delete ${names} from ${target}/ (pip uninstall does not look there)`
					: prefix ? `delete ${names} from ${prefix}/ (pip uninstall does not look there)`
					: root ? `delete ${names} from ${root}/ (pip uninstall does not look there)`
					: `pip uninstall ${names}`,
			});
		} else if ((tool === "docker" || tool === "podman") && (w[1] === "pull" || (w[1] === "image" && w[2] === "pull"))) {
			const args = w.slice(w[1] === "image" ? 3 : 2);
			if (installsNothing(args)) continue;
			const image = operands(args, PULL_VALUED)[0] ?? "an image";
			found.push({ what: `the container image ${image}`, where: `${tool}'s image store`, undo: `${tool} rmi ${image}` });
		} else if (tool === "brew" && (w[1] === "install" || w[1] === "reinstall")) {
			if (installsNothing(w.slice(2))) continue;
			const pkgs = operands(w.slice(2), []);
			found.push({
				what: `${pkgs.join(", ")} (Homebrew)`,
				where: "Homebrew's prefix (`brew --prefix`), shared with everything else on this machine that uses Homebrew",
				undo: `brew uninstall ${pkgs.join(" ")}`,
			});
		}
	}
	return found;
}

export default function (pi: ExtensionAPI) {
	pi.on("tool_result", async (event, ctx) => {
		if (event.toolName !== "bash" || event.isError) return;
		const command = typeof event.input.command === "string" ? event.input.command : "";
		const cwd = ctx?.cwd ?? process.cwd();
		const installs = describe(command, cwd);
		if (installs.length === 0) return;

		const stamp = new Date().toISOString().replace(/\.\d+Z$/, "Z");
		try {
			appendFileSync(
				join(agentDir(), "installs.log"),
				installs.map((i) => `${stamp}\t${cwd}\t${i.what}\t${i.where}\tremove: ${i.undo}\n`).join(""),
			);
		} catch {
			// the note below still reaches the user
		}
		const lines = installs.map((i) => `- ${i.what}\n  where: ${i.where}\n  remove: ${i.undo}`);
		const note =
			"[install-notes] This command installed software. Tell the user in your report - what, where it lives, " +
			`and how to remove it (also logged in ${join(agentDir(), "installs.log")}):\n${lines.join("\n")}`;
		return { content: [...event.content, { type: "text", text: note }] };
	});
}

/**
 * trust-guard: project trust is never granted to home, the filesystem root, or
 * a folder that holds credentials, and never inherited from one.
 *
 * Project trust decides whether a folder's own .pi/ - its settings, extensions,
 * skills and system-prompt files - loads, and an extension in there runs with
 * this install's access. A saved decision covers every folder below the one it
 * names, and pi's trust prompt offers "Trust parent folder": accepted once in
 * ~/notes, that trusts ~ itself, and with it every repository cloned anywhere
 * in the home folder, including ones not opened yet. defaultProjectTrust
 * "never" (templates/settings.json) stops a new folder being trusted silently;
 * it does not stop that.
 *
 * So for a folder on the list this answers "no" before pi consults its saved
 * decisions, and a saved "yes" on a listed folder is not passed down to the
 * folders under it. A project trusted by its own name is unaffected. The list
 * is untrustedFolders in config/elm-pi.json (ELM_UNTRUSTED_EXACT and
 * ELM_UNTRUSTED_TREE through runtime.env) plus every ancestor of home - the
 * same list the launcher uses to refuse a session started in one of them.
 *
 * Only agent-dir and command-line extensions see project_trust, which is why
 * this is a local extension and on the launcher's POLICY_EXTENSIONS. A
 * command-line --approve still overrides it: pi applies that first.
 */
import { readFileSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const HOME = process.env.HOME || homedir();

/** Absolute and symlink-resolved, as pi keys trust.json. */
function canonical(path: string): string {
	const expanded = path === "~" ? HOME : path.startsWith("~/") ? join(HOME, path.slice(2)) : path;
	const absolute = resolve(expanded);
	try {
		return realpathSync(absolute);
	} catch {
		return absolute; // a folder that does not exist on this machine
	}
}

const listed = (name: string) =>
	(process.env[name] ?? "")
		.split("\n")
		.map((entry) => entry.trim())
		.filter(Boolean)
		.map(canonical);

function withAncestors(path: string): string[] {
	const out = [path];
	for (let up = dirname(path); up !== out[out.length - 1]; up = dirname(up)) out.push(up);
	return out;
}

const EXACT = new Set([...listed("ELM_UNTRUSTED_EXACT"), ...withAncestors(canonical(HOME))]);
const TREES = listed("ELM_UNTRUSTED_TREE");

export function untrusted(dir: string): boolean {
	return EXACT.has(dir) || TREES.some((tree) => dir === tree || dir.startsWith(`${tree}/`));
}

/** The saved decision pi would apply: the nearest folder at or above dir in trust.json. */
function nearestSaved(dir: string): { path: string; trusted: boolean } | undefined {
	let saved: Record<string, unknown>;
	try {
		const agentDir = process.env.PI_CODING_AGENT_DIR;
		if (!agentDir) return undefined;
		saved = JSON.parse(readFileSync(join(agentDir, "trust.json"), "utf8"));
	} catch {
		return undefined; // no file yet, or one pi itself will complain about
	}
	for (const path of withAncestors(dir)) {
		const value = saved[path];
		if (value === true || value === false) return { path, trusted: value };
	}
	return undefined;
}

export default function (pi: ExtensionAPI) {
	pi.on("project_trust", async (event, ctx) => {
		const dir = canonical(event.cwd);
		const tell = (message: string) => {
			if (ctx.hasUI) ctx.ui.notify(message, "warning");
		};

		if (untrusted(dir)) {
			tell(
				`elm-pi: ${dir} is never trusted as a project, so its .pi/ settings and extensions are not loaded. ` +
					"Work in a project folder instead. See LOCKDOWN.md.",
			);
			return { trusted: "no" };
		}

		const saved = nearestSaved(dir);
		if (saved?.trusted && saved.path !== dir && untrusted(saved.path)) {
			tell(
				`elm-pi: the trust saved for ${saved.path} would cover every folder under it, so it is ignored here. ` +
					"To trust this project, run /trust in it and choose Trust (not the parent folder).",
			);
			return { trusted: "no" };
		}

		return { trusted: "undecided" };
	});
}

