    ENV_KEYS = PI_AI / "dist/env-api-keys.js"
    # In the list though no pi 1.4 file reads them: commercial-provider keys
    # other SDKs and older pi releases read. Unsetting them costs nothing.
    KEPT_DELIBERATELY = {"OPENAI_ORGANIZATION", "GOOGLE_GENERATIVE_AI_API_KEY"}

    def configured(self):
        return set(json.loads((ROOT / "config/elm-pi.json").read_text())["providerCredentials"])

    @unittest.skipUnless(ENV_KEYS.is_file(), "pi-ai is not installed in this checkout")
    def test_every_credential_pi_ai_reads_is_scrubbed(self):
        source = self.ENV_KEYS.read_text()
        env_map = re.search(r"const envMap = \{(.*?)\};", source, re.S).group(1)
        names = set(re.findall(r':\s*"([A-Z][A-Z0-9_]+)"', env_map))
        for listed in re.findall(r"return \[([^\]]*)\]", source):
            names |= set(re.findall(r'"([A-Z][A-Z0-9_]+)"', listed))
        names |= set(re.findall(r'export const \w+_ENV = "([A-Z][A-Z0-9_]+)"', source))
        self.assertGreater(len(names), 35)
        self.assertEqual(set(), names - self.configured(), "pi reads these and the launcher leaves them set")

    @unittest.skipUnless(PI_AI.is_dir() and PI_CORE.is_dir(), "pi is not installed in this checkout")
    def test_no_stale_names_in_the_scrub_list(self):
        text = []
        for tree in (PI_AI / "dist", PI_CORE / "dist"):
            for path in tree.rglob("*.js"):
                text.append(path.read_text(errors="replace"))
        text = "\n".join(text)
        stale = {n for n in self.configured() - self.KEPT_DELIBERATELY if f'"{n}"' not in text}
        self.assertEqual(set(), stale, "no file in this pi reads these")

    def test_huggingface_uses_pis_name(self):
        self.assertIn("HF_TOKEN", self.configured())
        self.assertNotIn("HUGGINGFACE_API_KEY", self.configured())


if __name__ == "__main__":
    unittest.main()

"""lib/node-guard.mjs, case by case, in a temporary install of its own.

The guard keeps packages from outside the install out of pi, whichever loader
asks: Node's (require, import, require.resolve) through a resolve hook, and
jiti's through vm.runInThisContext. A copy is placed in a temporary install, so
its root is known and nothing here touches the checkout:

    base/
      node_modules/above/index.js           a package above the install
      .node_modules/globalish.js            a "global folder" above it
      outside/node_modules/far/index.js      a package elsewhere
      outside/project/ext.js                 a project file, not a package
      inst/                                 the install (the guard's root)
        lib/node-guard.mjs
        node_modules/inside/index.js
        agent/npm/node_modules/pkg/index.js
        agent/extensions/local.ts
        links/to-outside -> ../../outside   a link out of the install
      link-to-inst -> inst                  a link into it

Each case states where a file is and what the guard must decide; one node
process answers every case.
"""

import json
import os
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GUARD = ROOT / "lib/node-guard.mjs"


def node():
    """The bundled node, or one on PATH with module.registerHooks (22.15+)."""
    bundled = ROOT / ".node/bin/node"
    if bundled.exists():
        return str(bundled)
    found = shutil.which("node")
    if found and subprocess.run([found, "-e", "process.exit(typeof require('node:module').registerHooks === 'function' ? 0 : 1)"],
                                capture_output=True).returncode == 0:
        return found
    return None


# path (from base) -> is it a package from outside the install?
OUTSIDE = {
    # the install's own files and packages
    "inst/node_modules/inside/index.js": False,
    "inst/agent/npm/node_modules/pkg/index.js": False,
    "inst/agent/extensions/local.ts": False,
    "inst/lib/node-guard.mjs": False,
    "inst/node_modules": False,
    "inst/agent/npm/node_modules/pkg/missing-file.js": False,
    # a file not there yet, under a link into the install: placed by its folder
    "link-to-inst/agent/npm/node_modules/pkg/missing-file.js": False,
    "inst/links/to-outside/node_modules/far/missing-file.js": True,
    # reached through a link into the install: still its own
    "link-to-inst/node_modules/inside/index.js": False,
    "link-to-inst/agent/npm/node_modules/pkg/index.js": False,
    "link-to-inst/agent/extensions/local.ts": False,
    # packages from anywhere else
    "node_modules/above/index.js": True,
    "node_modules": True,
    ".node_modules/globalish.js": True,
    ".node_libraries/lib.js": True,
    "outside/node_modules/far/index.js": True,
    "outside/node_modules/far/missing-file.js": True,
    "outside/node_modules/@scope/pkg/index.js": True,
    "outside/a/b/c/node_modules/deep/index.js": True,
    # through a link out of the install: where it really is decides
    "inst/links/to-outside/node_modules/far/index.js": True,
    # files that are not in a package directory: left alone
    "outside/project/ext.js": False,
    "outside/project/node_modules_backup/x.js": False,
    "outside/project/my-node_modules/x.js": False,
    "outside/project/node_modules.js": False,
    "outside/project/.node_modules_old/x.js": False,
    "outside/project/Node_Modules/x.js": False,
    "outside/project/x.node_modules/y.js": False,
    "inst/links/to-outside/project/ext.js": False,
    # a sibling whose name starts with the install's
    "inst-old/node_modules/x/index.js": True,
    "inst-old/lib/thing.js": False,
}

FILES = [
    "node_modules/above/index.js", ".node_modules/globalish.js", ".node_libraries/lib.js",
    "outside/node_modules/far/index.js", "outside/node_modules/@scope/pkg/index.js",
    "outside/a/b/c/node_modules/deep/index.js", "outside/project/ext.js",
    "outside/project/node_modules_backup/x.js", "outside/project/my-node_modules/x.js",
    "outside/project/node_modules.js", "outside/project/.node_modules_old/x.js",
    "outside/project/Node_Modules/x.js", "outside/project/x.node_modules/y.js",
    "inst/node_modules/inside/index.js", "inst/agent/npm/node_modules/pkg/index.js",
    "inst/agent/extensions/local.ts", "inst-old/node_modules/x/index.js", "inst-old/lib/thing.js",
]

# vm.runInThisContext(code, options) -> "ran" or "refused"
VM = {
    "options_with_an_outside_package": ({"filename": "outside/node_modules/far/index.js"}, "refused"),
    "a_string_filename_outside": ("outside/node_modules/far/index.js", "refused"),
    "a_package_above_the_install": ({"filename": "node_modules/above/index.js"}, "refused"),
    "a_global_folder": ({"filename": ".node_modules/globalish.js"}, "refused"),
    "the_installs_own_package": ({"filename": "inst/agent/npm/node_modules/pkg/index.js"}, "ran"),
    "the_installs_own_extension": ({"filename": "inst/agent/extensions/local.ts"}, "ran"),
    "a_project_file": ({"filename": "outside/project/ext.js"}, "ran"),
    "through_a_link_into_the_install": ({"filename": "link-to-inst/agent/npm/node_modules/pkg/index.js"}, "ran"),
    "through_a_link_out_of_the_install": ({"filename": "inst/links/to-outside/node_modules/far/index.js"}, "refused"),
    "no_options": (None, "ran"),
    "options_without_a_filename": ({}, "ran"),
    "an_empty_filename": ({"filename": ""}, "ran"),
    "the_default_name": ({"filename": "evalmachine.<anonymous>"}, "ran"),
    "a_relative_package_path": ({"filename": "node_modules/x/index.js", "relative": True}, "refused"),
    # not the guard's to judge: Node refuses it with its own error, as without the guard
    "a_numeric_filename": ({"filename": 7}, "node's own error"),
    "other_options_are_kept": ({"filename": "outside/project/ext.js", "lineOffset": 3}, "ran"),
}

# what each loader may bring in, from a file inside the install
LOAD = {
    "require_a_package_above": ("require", "above", "refused"),
    "import_a_package_above": ("import", "above", "refused"),
    "resolve_a_package_above": ("resolve", "above", "refused"),
    "require_the_installs_own_package": ("require", "inside", "loaded"),
    "import_the_installs_own_package": ("import", "inside", "loaded"),
    "resolve_the_installs_own_package": ("resolve", "inside", "loaded"),
    "require_a_builtin": ("require", "node:path", "loaded"),
    "import_a_builtin": ("import", "node:path", "loaded"),
    "require_a_missing_package": ("require", "no-such-package-anywhere", "missing"),
    "require_an_outside_file_by_path": ("require", "@outside/project/ext.js", "loaded"),
    "require_an_outside_package_file_by_path": ("require", "@outside/node_modules/far/index.js", "refused"),
    "import_an_outside_package_file_by_path": ("import", "@outside/node_modules/far/index.js", "refused"),
}

RUNNER = r"""
import { createRequire } from "node:module";
import vm from "node:vm";
import { pathToFileURL } from "node:url";
import { join } from "node:path";
const [base, casesJson] = process.argv.slice(1);
const cases = JSON.parse(casesJson);
const { outsideFile } = await import(pathToFileURL(join(base, "inst/lib/node-guard.mjs")).href);
const out = { outside: {}, vm: {}, load: {}, env: {} };
for (const rel of cases.outside) out.outside[rel] = outsideFile(join(base, rel));
for (const [name, [options]] of Object.entries(cases.vm)) {
  let arg = options;
  if (options && typeof options === "object" && typeof options.filename === "string" && options.filename)
    arg = { ...options, filename: options.relative ? options.filename : join(base, options.filename) };
  if (arg && typeof arg === "object") delete arg.relative;
  if (typeof options === "string") arg = join(base, options);
  try { vm.runInThisContext("1 + 1", arg ?? undefined); out.vm[name] = "ran"; }
  catch (e) { out.vm[name] = e.message.startsWith("elm-pi: refusing") ? "refused" : "threw: " + e.message; }
}
const from = join(base, "inst/agent/extensions/local.ts");
const req = createRequire(from);
for (const [name, [how, what]] of Object.entries(cases.load)) {
  const target = what.startsWith("@") ? join(base, what.slice(1)) : what;
  const classify = (e) => e.message.startsWith("elm-pi: refusing") ? "refused" : (e.code === "MODULE_NOT_FOUND" || e.code === "ERR_MODULE_NOT_FOUND") ? "missing" : "threw: " + e.message;
  try {
    if (how === "require") req(target);
    else if (how === "resolve") req.resolve(target);
    else await import(target.startsWith("/") ? pathToFileURL(target).href : target.startsWith("node:") ? target : pathToFileURL(req.resolve(target)).href);
    out.load[name] = "loaded";
  } catch (e) { out.load[name] = classify(e); }
}
for (const key of ["LD_LIBRARY_PATH", "DYLD_FALLBACK_LIBRARY_PATH", "OPENSSL_CONF", "ELM_PI_STASH__LD_LIBRARY_PATH", "ELM_PI_STASH__", "KEEP"])
  out.env[key] = process.env[key] ?? null;
console.log(JSON.stringify(out));
"""


class NodeGuardCaseTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        binary = node()
        if binary is None:
            raise unittest.SkipTest("needs a node with module.registerHooks")
        cls.tmp = Path(tempfile.mkdtemp()).resolve()
        base = cls.tmp
        try:
            for rel in FILES:
                path = base / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text('module.exports = "loaded";\n' if rel.endswith(".js") else "export default 1;\n")
            for name, rel in (("above", "node_modules/above"), ("inside", "inst/node_modules/inside"),
                              ("far", "outside/node_modules/far")):
                (base / rel / "package.json").write_text(json.dumps({"name": name, "main": "index.js"}))
            (base / "inst/lib").mkdir(parents=True)
            (base / "inst/lib/node-guard.mjs").write_text(GUARD.read_text())
            (base / "inst/links").mkdir()
            (base / "inst/links/to-outside").symlink_to(base / "outside")
            (base / "link-to-inst").symlink_to(base / "inst")
            cases = {"outside": list(OUTSIDE), "vm": {k: [v[0]] for k, v in VM.items()},
                     "load": {k: [v[0], v[1]] for k, v in LOAD.items()}}
            env = {"PATH": "/usr/bin:/bin", "HOME": str(base), "ELM_PI_STASH__LD_LIBRARY_PATH": "/conda/lib",
                   "ELM_PI_STASH__DYLD_FALLBACK_LIBRARY_PATH": "/opt/lib", "ELM_PI_STASH__OPENSSL_CONF": "/etc/ssl.cnf",
                   "ELM_PI_STASH__": "nameless", "KEEP": "kept"}
            run = subprocess.run([binary, "--import", str(base / "inst/lib/node-guard.mjs"), "--input-type=module",
                                  "-e", RUNNER, str(base), json.dumps(cases)],
                                 capture_output=True, text=True, env=env, cwd=base / "outside/project", timeout=120)
            if run.returncode != 0:
                raise AssertionError(run.stderr[-3000:])
            cls.out = json.loads(run.stdout)
            allowed = subprocess.run([binary, "--import", str(base / "inst/lib/node-guard.mjs"), "--input-type=module",
                                      "-e", RUNNER, str(base), json.dumps(cases)],
                                     capture_output=True, text=True, env={**env, "ELM_PI_ALLOW_EXTERNAL_MODULES": "1"},
                                     cwd=base / "outside/project", timeout=120)
            if allowed.returncode != 0:
                raise AssertionError(allowed.stderr[-3000:])
            cls.allowed = json.loads(allowed.stdout)
        except BaseException:
            shutil.rmtree(cls.tmp, ignore_errors=True)
            raise

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    # the environment the guard hands back to the agent's commands
    def test_a_stashed_library_path_is_restored(self):
        self.assertEqual("/conda/lib", self.out["env"]["LD_LIBRARY_PATH"])

    def test_every_stashed_variable_is_restored(self):
        self.assertEqual(("/opt/lib", "/etc/ssl.cnf"),
                         (self.out["env"]["DYLD_FALLBACK_LIBRARY_PATH"], self.out["env"]["OPENSSL_CONF"]))

    def test_the_stash_names_are_removed(self):
        self.assertIsNone(self.out["env"]["ELM_PI_STASH__LD_LIBRARY_PATH"])

    def test_a_stash_with_no_name_restores_nothing_and_goes(self):
        self.assertIsNone(self.out["env"]["ELM_PI_STASH__"])

    def test_other_variables_are_untouched(self):
        self.assertEqual("kept", self.out["env"]["KEEP"])


def _outside(self, rel, want):
    self.assertIs(want, self.out["outside"][rel], rel)


def _vm(self, name, want):
    if want == "node's own error":
        self.assertTrue(self.out["vm"][name].startswith("threw: "), self.out["vm"][name])
        self.assertEqual(self.out["vm"][name], self.allowed["vm"][name])
        return
    self.assertEqual(want, self.out["vm"][name])
    # with the check lifted, everything runs
    self.assertEqual("ran", self.allowed["vm"][name])


def _load(self, name, want):
    self.assertEqual(want, self.out["load"][name])
    lifted = {"refused": "loaded"}.get(want, want)
    self.assertEqual(lifted, self.allowed["load"][name])


def _slug(text):
    return "".join(c if c.isalnum() else "_" for c in text).strip("_").lower()


for _rel, _want in OUTSIDE.items():
    setattr(NodeGuardCaseTests, f"test_{'outside' if _want else 'own'}_{_slug(_rel)}",
            lambda self, r=_rel, w=_want: _outside(self, r, w))
for _name, (_, _want) in VM.items():
    setattr(NodeGuardCaseTests, f"test_vm_{_name}", lambda self, n=_name, w=_want: _vm(self, n, w))
for _name, (_, _, _want) in LOAD.items():
    setattr(NodeGuardCaseTests, f"test_load_{_name}", lambda self, n=_name, w=_want: _load(self, n, w))


if __name__ == "__main__":
    unittest.main()

"""The policy extensions behave as their comments say, case by case.

Five pi extensions in templates/extensions/ carry this install's policy:

- protected-paths.ts refuses every file-writing tool on .git, node_modules
  and dotenv files, and leaves other tools alone;
- elm-only.ts empties every non-ELM provider catalogue and complains when a
  non-ELM model becomes current;
- trust-guard.ts answers "no" to project trust for home, the root, container
  and credential folders, and to trust inherited from one of them;
- workflow-model-scope.ts lets a workflow agent spawn only on a model the ELM
  gateway serves, under the provider that serves it;
- pinned-instructions.ts stores standing instructions per project and puts them
  back in the system prompt at session start, after compaction and on unpin.

Each extension is copied to a temporary folder and loaded under node against a
stub ExtensionAPI that records what it registers; the handlers are then driven
with events. One node process per TestCase class runs every case and prints
the results as one JSON object, and one generated test method checks each case.
tests/test_policy.py, tests/test_trust_guard.py and tests/test_project.py cover
the launcher side and the source text; nothing here repeats them.
"""

import hashlib
import json
import os
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
EXTENSIONS = ROOT / "templates/extensions"
CONFIG = json.loads((ROOT / "config/elm-pi.json").read_text())
QWEN = CONFIG["models"]["qwen"]
LLAMA = CONFIG["models"]["llama"]
MISTRAL = CONFIG["models"]["mistral"]

# pinned-instructions.ts imports typebox at run time only to describe its tool
# parameters. A stub keeps these tests independent of bootstrap.sh having run.
TYPEBOX_STUB = """
export const Type = {
  Object: (properties) => ({ type: "object", properties }),
  String: (options) => ({ type: "string", ...options }),
  Number: (options) => ({ type: "number", ...options }),
};
"""


def node():
    local = ROOT / ".node/bin/node"
    return str(local) if local.exists() else shutil.which("node")


def slug(text):
    return re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")[:80]


def run_extension(source, runner, payload, env=None, cwd=None):
    """Run `runner` under node with the extension copied to a temp folder.

    The runner reads the extension's file URL from argv[1] and the cases as
    JSON from stdin, and prints one JSON object.
    """
    binary = node()
    if not binary:
        raise unittest.SkipTest("needs node")
    work = Path(tempfile.mkdtemp())
    try:
        (work / "node_modules/typebox").mkdir(parents=True)
        (work / "node_modules/typebox/package.json").write_text(
            json.dumps({"name": "typebox", "type": "module", "main": "index.js"}))
        (work / "node_modules/typebox/index.js").write_text(TYPEBOX_STUB)
        target = work / source
        shutil.copy(EXTENSIONS / source, target)
        script = "import { pathToFileURL } from 'node:url';\n" \
                 "import { readFileSync } from 'node:fs';\n" \
                 "const SOURCE = pathToFileURL(process.argv[1]).href;\n" \
                 "const INPUT = JSON.parse(readFileSync(0, 'utf8'));\n" + runner
        run = subprocess.run([binary, "--no-warnings", "--input-type=module", "-e", script, str(target)],
                             input=json.dumps(payload), capture_output=True, text=True,
                             env={**os.environ, **(env or {})}, cwd=cwd or work, timeout=120)
    finally:
        shutil.rmtree(work, ignore_errors=True)
    if run.returncode != 0 and "ERR_UNKNOWN_FILE_EXTENSION" in run.stderr:
        raise unittest.SkipTest("this node cannot load TypeScript")
    if run.returncode != 0:
        raise AssertionError(f"node failed:\n{run.stderr}")
    return json.loads(run.stdout)


def generate(cls, cases, check, prefix="test_"):
    """Add one test method per case: check(self, case). A case with
    "bug": "<what>" is kept as an expected failure."""
    for case in cases:
        name = prefix + case["id"]
        if hasattr(cls, name):
            raise RuntimeError(f"duplicate test {name}")

        def test(self, case=case):
            check(self, case)

        test.__name__ = name
        test.__doc__ = case.get("doc")
        if case.get("bug"):
            test = unittest.expectedFailure(test)
        setattr(cls, name, test)


# ---------------------------------------------------------------- protected-paths

PROTECTED_RUNNER = r"""
const mod = await import(SOURCE);
const handlers = {};
mod.default({ on: (event, handler) => { handlers[event] = handler; } });
const out = { registered: Object.keys(handlers), cases: {} };
for (const c of INPUT.cases) {
  const notes = [];
  const ctx = c.ui ? { hasUI: true, ui: { notify: (m, level) => notes.push([m, level]) } } : { hasUI: false };
  const event = { toolName: c.tool };
  if (c.input !== null) event.input = c.input;
  const result = await handlers.tool_call(event, ctx);
  out.cases[c.id] = { result: result ?? null, notes };
}
console.log(JSON.stringify(out));
"""

GIT = '".git" is protected'
MODULES = '"node_modules" is protected'
DOTENV = "dotenv files are protected"

# (path, reason or None when the write is allowed). Every case goes through
# `replace`, the hashline tool that actually edits files on this install.
PROTECTED_PATHS = [
    (".git/config", GIT),
    ("./.git/config", GIT),
    ("/home/u/repo/.git/hooks/pre-commit", GIT),
    ("../.git/config", GIT),
    ("~/repo/.git/HEAD", GIT),
    ("repo\\.git\\config", GIT),                      # Windows separators
    ("C:\\repo\\.git\\info\\exclude", GIT),
    (".git", GIT),                                    # the folder itself
    ("vendor/lib/.git", GIT),                         # a submodule's .git file
    ("a//.git//config", GIT),                         # doubled separators
    (".git/", GIT),
    ("node_modules/lodash/index.js", MODULES),
    ("/srv/app/node_modules/.bin/tsc", MODULES),
    ("packages/app/node_modules/x/package.json", MODULES),
    ("node_modules", MODULES),
    (".git/node_modules/x", GIT),                     # the first protected segment names the reason
    ("node_modules/pkg/.git/config", MODULES),
    ("node_modules/pkg/.env", MODULES),
    (".env", DOTENV),
    ("./.env", DOTENV),
    ("config/.env", DOTENV),
    (".env.local", DOTENV),
    (".env.production", DOTENV),
    ("/srv/app/.env.test", DOTENV),
    (".env.sample", DOTENV),
    (".env.example.bak", DOTENV),                     # only the exact template name is exempt
    ("app\\.env", DOTENV),
    ("../../.env", DOTENV),
    ("src/main.py", None),
    (".gitignore", None),
    (".gitattributes", None),
    (".github/workflows/ci.yml", None),
    ("git/config", None),
    ("my.git/config", None),
    ("src/.git-blame-ignore-revs", None),
    ("node_modules_backup/x.js", None),
    ("node_module/x.js", None),
    ("my_node_modules/x.js", None),
    (".env.example", None),                           # a template: names, not values
    ("config/.env.example", None),
    ("config.environment", None),
    ("prod.env", None),
    (".envrc", None),
    (".env-old", None),
    (".environment", None),
    (".env/notes.txt", None),                         # only the file name is a dotenv test
    ("env", None),
    ("README.md", None),
]

PROTECTED_CASES = []
for i, (path, reason) in enumerate(PROTECTED_PATHS):
    PROTECTED_CASES.append({"id": f"replace_{i:02d}_{slug(path)}_{'blocked' if reason else 'allowed'}",
                            "tool": "replace", "input": {"path": path}, "expect": reason, "path": path})

# A case-insensitive filesystem (macOS's default APFS) writes .GIT/config into
# .git/config, so names are compared case-insensitively.
for path, reason in ((".GIT/config", GIT), ("NODE_MODULES/x/index.js", MODULES), (".ENV", DOTENV)):
    PROTECTED_CASES.append({"id": f"replace_{slug(path)}_case_variant_blocked", "tool": "replace",
                            "input": {"path": path}, "expect": reason, "path": path})

# Every tool that can change a file is guarded, under every name for the path.
for tool in ("write", "edit", "replace", "replace_match", "insert", "copy", "move", "undo_last_change"):
    if tool != "replace":
        PROTECTED_CASES.append({"id": f"{tool}_to_git_config_blocked", "tool": tool,
                                "input": {"path": ".git/config"}, "expect": GIT, "path": ".git/config"})
for key in ("file", "filePath", "file_path"):
    PROTECTED_CASES.append({"id": f"insert_names_dotenv_as_{slug(key)}", "tool": "insert",
                            "input": {key: ".env"}, "expect": DOTENV, "path": ".env"})
PROTECTED_CASES += [
    # The first non-empty string key is the path that is checked.
    {"id": "path_key_wins_over_file_key", "tool": "replace",
     "input": {"path": "notes.txt", "file": ".env"}, "expect": None},
    {"id": "empty_path_falls_through_to_file", "tool": "replace",
     "input": {"path": "", "file": ".env"}, "expect": DOTENV, "path": ".env"},
    {"id": "non_string_path_falls_through_to_file_path", "tool": "replace",
     "input": {"path": 42, "file_path": "node_modules/x"}, "expect": MODULES, "path": "node_modules/x"},
]

# Tools that do not write are not this extension's business, even on a dotenv file.
for tool, tool_input in (("read", {"path": ".env"}), ("grep", {"path": ".git", "pattern": "x"}),
                         ("find", {"path": "node_modules"}), ("ls", {"path": ".git"}),
                         ("bash", {"command": "echo KEY=1 > .env"}),
                         ("pin_instruction", {"instruction": "never edit .env"})):
    PROTECTED_CASES.append({"id": f"{tool}_is_not_a_writing_tool", "tool": tool,
                            "input": tool_input, "expect": None})

# A writing tool with no path cannot be checked: the hashline tools are refused,
# the builtin write/edit (which always carry one in practice) are let through.
for tool in ("replace", "replace_match", "insert", "copy", "move", "undo_last_change"):
    PROTECTED_CASES.append({"id": f"{tool}_without_a_path_is_refused", "tool": tool,
                            "input": {"anchor": "12#ab"}, "expect": "missing"})
for tool in ("write", "edit"):
    PROTECTED_CASES.append({"id": f"{tool}_without_a_path_passes", "tool": tool,
                            "input": {"content": "x"}, "expect": None})
PROTECTED_CASES += [
    {"id": "replace_with_no_input_at_all_is_refused", "tool": "replace", "input": None, "expect": "missing"},
    {"id": "replace_with_empty_path_only_is_refused", "tool": "replace", "input": {"path": ""}, "expect": "missing"},
    {"id": "blocked_write_notifies_the_user", "tool": "replace", "input": {"path": ".env"}, "ui": True,
     "expect": DOTENV, "path": ".env", "notes": [["Blocked replace to protected path: .env", "warning"]]},
    {"id": "allowed_write_does_not_notify", "tool": "replace", "input": {"path": "a.txt"}, "ui": True,
     "expect": None, "notes": []},
]


class ProtectedPathsTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.out = run_extension("protected-paths.ts", PROTECTED_RUNNER, {"cases": PROTECTED_CASES})

    def test_only_tool_calls_are_watched(self):
        self.assertEqual(["tool_call"], self.out["registered"])

    def check(self, case):
        got = self.out["cases"][case["id"]]
        expect = case["expect"]
        if expect is None:
            self.assertIsNone(got["result"])
        elif expect == "missing":
            self.assertEqual({"block": True, "reason":
                              f'{case["tool"]} must name the file it changes ("path"), so protected paths can be checked'},
                             got["result"])
        else:
            self.assertEqual({"block": True, "reason": f'Path "{case["path"]}" is protected: {expect}'},
                             got["result"])
        if "notes" in case:
            self.assertEqual(case["notes"], got["notes"])


generate(ProtectedPathsTests, PROTECTED_CASES, ProtectedPathsTests.check)


